const catalogCache=new Map();
async function fetchJSON(url,fresh=false){
 for(let attempt=0;attempt<2;attempt++){
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);
  try{const r=await fetch(url,{signal:controller.signal,cache:fresh?'no-store':'default'});if(!r.ok)throw Error('No se pudo cargar '+url+' ('+r.status+').');return await r.json()}
  catch(e){if(attempt===1)throw Error(e.name==='AbortError'?'La carga está tardando demasiado. Comprueba la conexión y vuelve a elegir el país o la sección.':e.message)}
  finally{clearTimeout(timer)}
 }
}
async function json(file){
 const url=st.dataRoot+file,cacheable=/^catalogo-/.test(file);
 if(cacheable&&catalogCache.has(url))return catalogCache.get(url);
 const data=await fetchJSON(url,file==='manifest.json');
 if(cacheable){catalogCache.set(url,data);if(catalogCache.size>8)catalogCache.delete(catalogCache.keys().next().value)}
 return data;
}
function message(s){$('notice').textContent=s}
function future(p){const now=new Date();const y=now.getFullYear(),m=now.getMonth()+1;if(/^\d{4}$/.test(p))return +p>y;if(/^\d{4}-\d{2}$/.test(p))return p>`${y}-${String(m).padStart(2,'0')}`;if(/^\d{4}-Q[1-4]$/.test(p))return +p.slice(0,4)>y||(+p.slice(0,4)===y&&+p.slice(-1)>Math.ceil(m/3));return false}
function normalize(s){return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()}

