function sourceLabel(row){
 const aliases={BCB:"Banco Central de Bolivia (BCB)",INE:"Instituto Nacional de Estadística (INE)",MEFP:"Ministerio de Economía y Finanzas Públicas (MEFP)",ASFI:"Autoridad de Supervisión del Sistema Financiero (ASFI)"};
 const org=String(row.organization||'').trim();
 if(org && normalize(org)!=='fuente oficial')return aliases[org]||org;
 const mapped=sourceInstitutions[row.area_code+'|'+row.source_file];
 if(mapped)return mapped;
 const source=String(row.source_name||'').trim();
 return aliases[source]||(source&&normalize(source)!=='fuente oficial'?source:'Institución pendiente de verificar');
}
function filtered(){const q=normalize($('search').value);return st.rows.filter(r=>(!st.favOnly||favs.has(r.series_id))&&normalize([r.public_name,r.territory_name,r.organization,r.measure,r.unit,r.frequency].join(' ')).includes(q))}
function renderList(){const rows=filtered(),pages=Math.max(1,Math.ceil(rows.length/40));st.page=Math.min(st.page,pages-1);$('count').textContent=fmt(rows.length)+' series';$('page').textContent=`${st.page+1} / ${pages}`;$('prev').disabled=st.page===0;$('next').disabled=st.page>=pages-1;
$('catalog').innerHTML=rows.slice(st.page*40,st.page*40+40).map(r=>`<div class="entry"><button class="pick ${st.selection.some(s=>s.row.series_id===r.series_id)?'active':''}" data-id="${r.series_id}">${esc(r.public_name)}<small>${esc(r.measure)} · ${esc(r.frequency)}<br>${esc(r.unit)} · ${esc(r.territory_name)}<br>${esc(r.last_period)} · ${fmt(r.last_value)}</small></button><button class="star" data-fav="${r.series_id}" aria-label="${favs.has(r.series_id)?'Quitar de':'Añadir a'} favoritos">${favs.has(r.series_id)?'★':'☆'}</button></div>`).join('')||'<p class="muted">No hay resultados en esta sección.</p>'}
async function loadSection(){const token=++st.token;st.rows=[];st.page=0;$('catalog').innerHTML='<p class="muted">Cargando sección…</p>';try{const s=st.area.sections[+$('section').value];const rows=await json(s.file);if(token!==st.token)return;st.rows=rows;st.page=0;renderList()}catch(e){if(token===st.token)$('catalog').textContent=e.message}}
function selectArea(area){st.area=area;document.querySelectorAll('#areas button').forEach(b=>{const on=b.dataset.area===area.code;b.classList.toggle('active',on);b.setAttribute('aria-pressed',on)});$('section').innerHTML=area.sections.map((s,i)=>`<option value="${i}">${esc(s.name)} (${s.count})</option>`).join('');$('search').value='';loadSection()}
function compatible(a,b){return a.frequency===b.frequency&&a.unit===b.unit&&a.currency_code===b.currency_code&&a.measure===b.measure&&a.reference_year===b.reference_year}
async function add(id){if(st.selection.some(s=>s.row.series_id===id)){if(st.compare)remove(id);return}let row=st.rows.find(r=>r.series_id===id);if(!row)return;if(!st.compare){st.detailToken++;st.selection=[];}if(st.selection.length>=4){message('Puedes seleccionar hasta cuatro series. Quita una para añadir otra.');return}if(st.selection.length&&!compatible(st.selection[0].row,row)){message('Estas series tienen distinta frecuencia, medida, unidad, moneda o base de referencia. Limpia la selección para consultar esta serie por separado.');return}
const token=st.detailToken;message('Cargando historial…');try{const bucket=Math.floor(id/500);let data=st.history.get(bucket);if(!data){data=await json(`historial-${bucket}.json`);if(st.history.size>=4)st.history.delete(st.history.keys().next().value);st.history.set(bucket,data)}if(token!==st.detailToken)return;if(st.selection.some(s=>s.row.series_id===id))return;if(st.selection.length>=4||st.selection.length&&!compatible(st.selection[0].row,row))return;const fichas=await json(`fichas-${bucket}.json`);if(token!==st.detailToken)return;if(st.selection.some(s=>s.row.series_id===id)||st.selection.length>=4)return;if(st.selection.length&&!compatible(st.selection[0].row,row))return;row=fichas[id]||row;st.selection.push({row,points:data[id]||[]});updateRange();renderList();draw()}catch(e){message(e.message)}}
function remove(id){st.detailToken++;st.selection=st.selection.filter(s=>s.row.series_id!==id);updateRange();renderList();draw()}
function periods(){return [...new Set(st.selection.flatMap(s=>s.points.map(p=>p[0])))].sort()}
function updateRange(){const ps=periods();for(const id of ['from','to']){$(id).innerHTML=ps.map(p=>`<option>${esc(p)}</option>`).join('');$(id).disabled=!ps.length}$('to').value=ps.at(-1)||'';st.tableLimit=200}
function viewed(){const from=$('from').value,to=$('to').value;return st.selection.map(s=>({...s,points:s.points.filter(p=>p[0]>=from&&p[0]<=to)}))}
function ordinal(p){if(/^\d{4}$/.test(p))return +p;if(/^\d{4}-\d{2}$/.test(p))return +p.slice(0,4)*12+(+p.slice(5)-1);if(/^\d{4}-Q[1-4]$/.test(p))return +p.slice(0,4)*4+(+p.slice(-1)-1);return null}
function temporal(row){return ['Anual','Mensual','Trimestral','Censal','Intercensal'].includes(row.frequency)&&!/decreto supremo|identificador normativo/i.test(row.public_name+' '+row.measure)}
function axisLabel(value,step,unit,magnitude){
 const scaled=/miles|millones/i.test(unit);let divisor=1,suffix='';
 if(!scaled){if(magnitude>=1e9){divisor=1e9;suffix=' mil M'}else if(magnitude>=1e6){divisor=1e6;suffix=' M'}else if(magnitude>=1e5){divisor=1e3;suffix=' mil'}}
 const precision=Math.min(12,Math.max(0,Math.ceil(-Math.log10(Math.abs(step/divisor)||1))+1));
 const clean=Math.abs(value)<Math.abs(step)*1e-7?0:value;
 return new Intl.NumberFormat('es-BO',{maximumFractionDigits:precision}).format(clean/divisor)+suffix+(/porcentaje/i.test(unit)||unit==='%'?'%':'');
}
function wrapText(text,width){const words=String(text).split(/\s+/),lines=[];let line='';for(const w of words){if(line.length+w.length+1>width&&line){lines.push(line);line=w}else line+=(line?' ':'')+w}if(line)lines.push(line);return lines}
function short(text,n){return text.length>n?text.slice(0,n-1)+'…':text}
function chartSVG(series,W=1000){const ps=[...new Set(series.flatMap(s=>s.points.map(p=>p[0])))].sort(),values=series.flatMap(s=>s.points.map(p=>p[1])).filter(Number.isFinite);if(!values.length)return '';let lo=Math.min(...values),hi=Math.max(...values);const pad=(hi-lo)*.08||Math.abs(hi)*.08||1;lo-=pad;hi+=pad;const headings=wrapText(series.length===1?series[0].row.public_name:'Comparación de indicadores',Math.floor((W-40)/9)),units=wrapText(series[0].row.unit+' · '+series[0].row.frequency,Math.floor((W-40)/7));const T=35+headings.length*22+units.length*18,H=Math.max(650,T+480),L=W<500?85:115,R=25,B=145,pw=W-L-R,ph=H-T-B;const numeric=ps.every(p=>ordinal(p)!==null),ords=ps.map(ordinal);const xmin=numeric?Math.min(...ords):0,xmax=numeric?Math.max(...ords):ps.length-1;const x=p=>L+((numeric?ordinal(p):ps.indexOf(p))-xmin)/(xmax-xmin||1)*pw,y=v=>T+(hi-v)/(hi-lo)*ph;let out=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(series[0].row.public_name)}"><rect width="${W}" height="${H}" fill="#101114"/>${headings.map((line,i)=>`<text x="20" y="${28+i*22}" fill="#f4f2ed" font-family="sans-serif" font-size="17" font-weight="bold">${esc(line)}</text>`).join('')}${units.map((line,i)=>`<text x="20" y="${35+headings.length*22+i*18}" fill="#b3b4ba" font-family="sans-serif" font-size="13">${esc(line)}</text>`).join('')}`;
for(let i=0;i<=4;i++){const v=lo+(hi-lo)*i/4,yy=y(v);out+=`<line x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}" stroke="#30333b"/><text x="${L-12}" y="${yy+5}" text-anchor="end" fill="#b3b4ba" font-family="sans-serif" font-size="12">${esc(axisLabel(v,(hi-lo)/4,series[0].row.unit,Math.max(Math.abs(lo),Math.abs(hi))))}</text>`}
const ticks=[...new Set([0,Math.floor((ps.length-1)/3),Math.floor(2*(ps.length-1)/3),ps.length-1])];for(const i of ticks)out+=`<text x="${x(ps[i])}" y="${H-B+28}" text-anchor="middle" fill="#b3b4ba" font-family="sans-serif" font-size="14">${esc(ps[i])}</text>`;
series.forEach((s,i)=>{let d='',previous=null;for(const p of s.points){if(!Number.isFinite(p[1])){previous=null;continue}const gap=previous&&['Anual','Mensual','Trimestral'].includes(s.row.frequency)&&ordinal(p[0])-ordinal(previous[0])>1;d+=`${previous&&!gap?'L':'M'}${x(p[0]).toFixed(2)},${y(p[1]).toFixed(2)} `;previous=p}out+=`<path d="${d}" fill="none" stroke="${colors[i]}" stroke-width="2.8"/>`;if(s.points.length<=120)for(const p of s.points)out+=`<circle cx="${x(p[0])}" cy="${y(p[1])}" r="3.5" fill="${colors[i]}"><title>${esc(s.row.public_name+' · '+p[0]+' · '+fmt(p[1])+' · '+p[2])}</title></circle>`;out+=`<text x="${L}" y="${H-B+55+i*17}" fill="${colors[i]}" font-family="sans-serif" font-size="12">${esc(short(s.row.public_name,Math.floor((W-L-R)/6.5)))}</text>`});out+=`<text x="${L}" y="${H-25}" fill="#b3b4ba" font-family="sans-serif" font-size="11">${esc('Fuentes: '+[...new Set(series.map(s=>sourceLabel(s.row)))].join(' · ').slice(0,Math.floor((W-L-R)/6)))}</text><text x="${W-R}" y="${H-6}" text-anchor="end" fill="#ffe18a" font-family="sans-serif" font-size="${W<500?13:17}" font-weight="bold">bernalmauricio.com · Economicus</text></svg>`;return out}
function draw(){const ss=viewed(),has=ss.some(s=>s.points.length);$('csv').disabled=!has;$('png').disabled=!has||!st.selection.every(s=>temporal(s.row));$('tableWrap').hidden=!has;$('selected').hidden=!st.compare;$('clear').hidden=!st.compare;$('selected').innerHTML=st.selection.map((s,i)=>`<div class="chip" style="border-color:${colors[i]}"><span>${esc(s.row.public_name)}</span><button data-remove="${s.row.series_id}" aria-label="Quitar serie">×</button></div>`).join('');if(!st.selection.length){$('title').textContent='Elige un indicador';$('subtitle').textContent='Toca cualquier indicador para verlo. Para juntar varios, activa Comparar series.';$('chart').innerHTML='<p class="empty">Selecciona una serie del catálogo para explorar su historial.</p>';$('sources').innerHTML='';message('');return}
$('title').textContent=st.selection.length===1?st.selection[0].row.public_name:'Comparación de indicadores';$('subtitle').textContent=st.selection[0].row.unit+' · '+st.selection[0].row.frequency;const warnings=[];if($('from').value>$('to').value)warnings.push('El período inicial debe ser anterior al final.');if(ss.some(s=>s.points.some(p=>future(p[0]))))warnings.push('Hay períodos futuros: consulta la descripción y el calendario de la fuente. No son resultados históricos observados.');if(st.selection.length>1)warnings.push('La compatibilidad de unidades no garantiza equivalencia económica. Revisa medida, territorio y fuente.');if(!st.selection.every(s=>temporal(s.row)))warnings.push('Referencia censal, estructural, territorial o de campaña: consulta la tabla; no se dibuja como una serie temporal continua.');message(warnings.join(' '));$('chart').innerHTML=!has?'<p class="empty">No hay observaciones en este intervalo.</p>':st.selection.every(s=>temporal(s.row))?chartSVG(ss,Math.max(340,$('chart').clientWidth-24)):'<p class="empty">Este indicador se presenta en la tabla de observaciones.</p>';
$('sources').innerHTML=st.selection.map(s=>`<div class="source"><strong>${esc(s.row.public_name)}</strong><p>${esc(s.row.description)}</p><p>Fuente: ${esc(sourceLabel(s.row))} · Archivo: ${esc(s.row.source_file)}</p><p>Medida: ${esc(s.row.measure)} · Territorio: ${esc(s.row.territory_name)} · Moneda: ${esc(s.row.currency_code||'No monetaria')} ${s.row.reference_year?'· Referencia: '+esc(s.row.reference_year):''}</p><p>Código: ${esc(s.row.series_code)}</p></div>`).join('');renderTable(ss)}
function renderTable(ss=viewed()){const rows=ss.flatMap(s=>s.points.map(p=>({s:s.row.public_name,p}))).sort((a,b)=>b.p[0].localeCompare(a.p[0]));$('table').innerHTML=rows.slice(0,st.tableLimit).map(({s,p})=>`<tr><td>${esc(p[0])}</td><td>${esc(s)}</td><td>${fmt(p[1])}</td><td>${esc(p[2])}</td></tr>`).join('');$('moreRows').hidden=rows.length<=st.tableLimit}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function csvCell(v){let t=String(v??'');if(typeof v!=='number'&&/^[=+\-@]/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"'}
$('csv').onclick=()=>{const rows=[['Código','Indicador','Período','Valor','Unidad','Frecuencia','Estado','Fuente','Archivo fuente','Territorio']];for(const s of viewed())for(const p of s.points)rows.push([s.row.series_code,s.row.public_name,p[0],p[1],s.row.unit,s.row.frequency,p[2],sourceLabel(s.row),s.row.source_file,s.row.territory_name]);download(new Blob(['\ufeff'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'economicus-datos.csv')};
$('png').onclick=async()=>{if(!$('chart').querySelector('svg'))return;const url=URL.createObjectURL(new Blob([chartSVG(viewed())],{type:'image/svg+xml;charset=utf-8'}));try{const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url});const canvas=document.createElement('canvas');canvas.width=2000;canvas.height=Math.round(2000*(+(chartSVG(viewed()).match(/viewBox="0 0 1000 (\d+)/)?.[1]||650))/1000);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error();download(blob,'economicus-grafico.png')}catch{message('No se pudo exportar el gráfico. Intenta nuevamente.')}finally{URL.revokeObjectURL(url)}};
$('catalog').onclick=e=>{const pick=e.target.closest('[data-id]'),star=e.target.closest('[data-fav]');if(pick)add(+pick.dataset.id);if(star){const id=+star.dataset.fav;favs.has(id)?favs.delete(id):favs.add(id);try{localStorage.setItem('economicus-favoritos-web',JSON.stringify([...favs]))}catch{}renderList()}};
$('selected').onclick=e=>{const b=e.target.closest('[data-remove]');if(b)remove(+b.dataset.remove)};$('areas').onclick=e=>{const b=e.target.closest('[data-area]');if(b)selectArea(st.manifest.areas.find(a=>a.code===b.dataset.area))};$('section').onchange=loadSection;$('search').oninput=()=>{st.page=0;renderList()};$('favOnly').onclick=()=>{st.favOnly=!st.favOnly;$('favOnly').setAttribute('aria-pressed',st.favOnly);st.page=0;renderList()};$('prev').onclick=()=>{st.page--;renderList();$('catalog').scrollTop=0};$('next').onclick=()=>{st.page++;renderList();$('catalog').scrollTop=0};$('clear').onclick=()=>{st.detailToken++;st.selection=[];updateRange();renderList();draw()};$('from').onchange=$('to').onchange=()=>{st.tableLimit=200;draw()};$('moreRows').onclick=()=>{st.tableLimit+=200;renderTable()};
function setMode(compare){st.detailToken++;st.compare=compare;$('singleMode').setAttribute('aria-pressed',!compare);$('compareMode').setAttribute('aria-pressed',compare);if(!compare&&st.selection.length>1)st.selection=[st.selection[st.selection.length-1]];updateRange();renderList();draw();if(compare)message('Selecciona hasta cuatro series compatibles para compararlas.');}
$('singleMode').onclick=()=>setMode(false);$('compareMode').onclick=()=>setMode(true);
async function loadCountry(code){const country=st.countries.find(c=>c.code===code);if(!country?.available)return;st.token++;st.detailToken++;st.selection=[];st.rows=[];st.history.clear();st.dataRoot=country.dataRoot;updateRange();draw();$('countryHeading').textContent=country.name.toUpperCase()+' · BIBLIOTECA DE INDICADORES';$('snapshot').textContent='Cargando catálogo…';try{st.manifest=await json('manifest.json');const date=st.manifest.metadata.published_at?.slice(0,10)||'No indicada';$('snapshot').textContent=`${fmt(st.manifest.series)} series · ${st.manifest.areas.length} áreas · Base publicada: ${date}`;$('areas').innerHTML=st.manifest.areas.map(a=>`<button data-area="${a.code}" aria-pressed="false">${esc(a.name)}</button>`).join('');selectArea(st.manifest.areas[0])}catch(e){$('snapshot').textContent=e.message}}
$('country').onchange=()=>loadCountry($('country').value);
(async()=>{try{st.countries=await fetchJSON('paises.json',true);$('country').innerHTML=st.countries.map(c=>`<option value="${esc(c.code)}" ${c.available?'':'disabled'}>${esc(c.name)}${c.available?'':' · Sin datos cargados'}</option>`).join('');const first=st.countries.find(c=>c.available);if(first){$('country').value=first.code;await loadCountry(first.code)}}catch(e){$('snapshot').textContent=e.message}})();

let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(st.selection.length)draw()},150)});
